using System;
using System.Collections;
using System.Collections.Generic;
using System.Globalization;
using UnityEngine;
using UnityEngine.Networking;

/// <summary>Published flat-video catalogs, generated by the existing art importer.</summary>
public static class UICardVideoCatalog
{
    // Catalogs live beside the movie folders, which contain MP4s only.
    public const string CharacterFolder = "Character_Animated";
    public const string CharacterVideoRoot = "art_assets/" + CharacterFolder + "/";
    public const string CharacterManifestPath = "art_assets/" + CharacterFolder + ".json";
    public const string EnemyManifestPath = "art_assets/Enemy_Animated.json";
    [Serializable] public sealed class PublishedCatalog { public string[] videos; }

    public static bool TryGetIdentity(string file, out int id, out int variant)
    {
        id = variant = 0;
        if (string.IsNullOrEmpty(file) || !file.EndsWith(".mp4", StringComparison.Ordinal)) return false;
        string[] parts = file.Substring(0, file.Length - 4).Split('_');
        if (parts.Length > 2 || !int.TryParse(parts[0], NumberStyles.None, CultureInfo.InvariantCulture, out int number) || number <= 0)
            return false;
        int form = 1;
        if (parts.Length == 2 && (!int.TryParse(parts[1], NumberStyles.None, CultureInfo.InvariantCulture, out form) || form <= 1))
            return false;
        if (file != UICardVideoPlayer.MediaKey(number, form) + ".mp4") return false;
        id = number; variant = form; return true;
    }

    private static IEnumerator LoadPaths(string manifest, string folder, HashSet<string> available, Action<string> onError)
    {
        available.Clear();
        if (!StreamingAssetSpriteLoader.TryBuildRequestUrl(manifest, out string url)) yield break;
        using (var request = UnityWebRequest.Get(url))
        {
            yield return request.SendWebRequest();
            if (request.result != UnityWebRequest.Result.Success)
            { onError?.Invoke(request.error); yield break; }
            PublishedCatalog catalog = null;
            try { catalog = JsonUtility.FromJson<PublishedCatalog>(request.downloadHandler.text); }
            catch (Exception error) { onError?.Invoke(error.Message); }
            if (catalog?.videos == null) yield break;
            foreach (string file in catalog.videos)
            {
                if (TryGetIdentity(file, out _, out _)) available.Add(folder + file);
                else onError?.Invoke("动态卡面清单包含无效的编号、形态或文件名：" + file);
            }
        }
    }

    public static IEnumerator LoadEnemies(HashSet<string> available, Action<string> onError) =>
        LoadPaths(EnemyManifestPath, "art_assets/Enemy_Animated/", available, onError);

    public static IEnumerator LoadCharacters(HashSet<string> available, Action<string> onError) =>
        LoadPaths(CharacterManifestPath, CharacterVideoRoot, available, onError);

    public static IEnumerator Load(HashSet<int> available, Action<string> onError)
    {
        available.Clear();
        var paths = new HashSet<string>(StringComparer.Ordinal);
        yield return LoadCharacters(paths, onError);
        foreach (string path in paths)
            if (TryGetIdentity(path.Substring(CharacterVideoRoot.Length), out int id, out int variant) && variant == 1)
                available.Add(id);
    }
}
